metrics.workdir_dsl:
workspace "Parcel Tracker" "A parcel delivery tracking platform" {
    configuration {
        scope "Landscape"
    }

    model {
        customer = person "Customer" "A customer who looks up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "The parcel delivery tracking platform, owned and operated by our company" {
            webPortal = container "Web Portal" "Where customers look up shipments" "Web application" {
                portalPricing = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Shared library"
            }

            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service" {
                dispatchPricing = component "Pricing Rules Library" "Computes delivery prices from weight and zone" "Shared library"
            }

            database = container "Database" "Stores shipments and dispatch records" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "An email delivery provider operated by a different organization"

        customer -> webPortal "looks up the status of their parcels" "Web"
        dispatchService -> emailProvider "sends customer notification emails through" "Email"
        webPortal -> database "stores shipments in" "SQL"
        dispatchService -> database "stores dispatch records in" "SQL"
    }

    views {
        systemContext parcelTracker "SystemContext" "Shows the Parcel Tracker system and the people and systems that interact with it" {
            include *
            autoLayout
        }

        container parcelTracker "Containers" "Shows the containers that make up the Parcel Tracker system" {
            include *
            autoLayout
        }

        component webPortal "WebPortalComponents" "Shows the components of the web portal" {
            include *
            autoLayout
        }

        component dispatchService "DispatchServiceComponents" "Shows the components of the dispatch service" {
            include *
            autoLayout
        }
    }
}
